do $$
declare admin_id uuid; staff_id uuid; other_id uuid; person bigint; employee bigint; shift bigint; branch bigint;
 code text; source_token text; receiver_token text; result jsonb; jid uuid:=gen_random_uuid();
begin
 select user_id into admin_id from public.staff_accounts where active and role='admin' limit 1;
 select user_id,person_id into staff_id,person from public.staff_accounts where active and role='staff' and person_id is not null limit 1;
 select user_id into other_id from public.staff_accounts where active and role='staff' and person_id<>person limit 1;
 select branch_id into branch from print_private.config;
 select id into employee from public.sales_employees where person_id=person and branch_id=branch limit 1;
 if employee is null then insert into public.sales_employees(branch_id,name,person_id) select branch,name,id from public.sales_people where id=person returning id into employee; end if;
 select id into shift from public.sales_shifts where branch_id=branch and status='open' limit 1;
 if shift is null then insert into public.sales_shifts(branch_id,employee_id,status) values(branch,employee,'open') returning id into shift;end if;
 insert into public.sales_shift_employees(shift_id,employee_id) values(shift,employee) on conflict do nothing;
 select a.user_id into other_id from public.staff_accounts a where a.active and a.role='staff' and a.person_id<>person and not exists(select 1 from public.sales_shift_employees se join public.sales_employees e on e.id=se.employee_id where se.shift_id=shift and e.person_id=a.person_id) limit 1;
 if other_id is null then raise exception 'No unrelated staff available for privacy test';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'role','authenticated')::text,true);
 result:=public.print_bridge_pair_code('source');code:=result->>'code';
 result:=print_private.device_api('pair','',jsonb_build_object('code',code,'expected_role','source','label','Rollback source'));
 source_token:=result->>'token';
 begin perform print_private.device_api('pair','',jsonb_build_object('code',code,'expected_role','source'));raise exception 'FAIL: reused code accepted';exception when sqlstate 'PT401' then null; end;
 result:=public.print_bridge_pair_code('receiver');
 result:=print_private.device_api('pair','',jsonb_build_object('code',result->>'code','expected_role','receiver','label','Rollback receiver'));receiver_token:=result->>'token';
 result:=print_private.device_api('enqueue',source_token,jsonb_build_object('id',jid,'filename','тест 30х40.tif','size',4,'sha256',repeat('a',64),'url','https://disk.yandex.ru/d/rollback-test','source_branch','Тест'));
 result:=print_private.device_api('enqueue',source_token,jsonb_build_object('id',jid,'filename','тест 30х40.tif','size',4,'sha256',repeat('a',64),'url','https://disk.yandex.ru/d/rollback-test','source_branch','Тест'));
 if (select count(*) from print_private.jobs where id=jid)<>1 then raise exception 'FAIL: duplicated job'; end if;
 result:=print_private.device_api('next',receiver_token,'{}');if result->>'id'<>jid::text then raise exception 'FAIL: wrong job'; end if;
 begin perform print_private.device_api('complete',source_token,jsonb_build_object('id',jid));raise exception 'FAIL: source completed job';exception when sqlstate 'PT403' then null; end;
 begin perform print_private.device_api('complete',receiver_token,jsonb_build_object('id',jid,'sha256',repeat('b',64),'size',4,'relative_path','тест 30х40.tif'));raise exception 'FAIL: bad hash accepted';exception when others then if sqlerrm like 'FAIL:%' then raise; end if;end;
 if (select downloaded_at from print_private.jobs where id=jid) is not null then raise exception 'FAIL: premature notification';end if;
 result:=print_private.device_api('complete',receiver_token,jsonb_build_object('id',jid,'sha256',repeat('a',64),'size',4,'relative_path','тест 30х40.tif'));
 result:=print_private.device_api('complete',receiver_token,jsonb_build_object('id',jid,'sha256',repeat('a',64),'size',4,'relative_path','тест 30х40.tif'));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',staff_id,'role','authenticated')::text,true);
 result:=public.print_bridge_files(shift);
 if jsonb_array_length(result)<>1 or (result->0->>'filename')<>'тест 30х40.tif' then raise exception 'FAIL: target staff cannot see notification';end if;
 if result::text like '%public_url%' or result::text like '%rollback-test%' then raise exception 'FAIL: download URL exposed';end if;
 perform public.print_bridge_read(shift,jid);result:=public.print_bridge_files(shift);
 if not (result->0->>'is_read')::boolean then raise exception 'FAIL: read not saved';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other_id,'role','authenticated')::text,true);
 begin perform public.print_bridge_files(shift);raise exception 'FAIL: another employee can see target notification';exception when sqlstate 'PT403' then null;end;
 begin perform public.print_bridge_pair_code('source');raise exception 'FAIL: staff created pairing';exception when sqlstate 'PT403' then null;end;
 if has_function_privilege('anon','public.print_bridge_pair_code(text)','execute') or has_function_privilege('authenticated','public.print_bridge_device_api(text,text,jsonb)','execute') or has_table_privilege('authenticated','print_private.jobs','select') then raise exception 'FAIL: excessive grants';end if;
end $$;
select 'bridge authorization, duplicate handling, checksum proof and notification scope passed' as result;
